/**
 * Workflow 4 — Vector Retrieval Engine
 * Node 1: Retrieval Validation & Metadata Filtering
 *
 * Single Responsibility:
 *   - Confirm upstream retrieval (Workflow 3) actually succeeded.
 *   - Re-validate the similarity threshold at this layer (defense in depth —
 *     do not blindly trust upstream status flags, especially given observed
 *     scoring anomalies in Workflow 3's output — see architecture notes).
 *   - Apply metadata filters IF the caller supplied filter criteria.
 *
 * SCHEMA GAP:
 *   `search_request` (Workflow 3 output) currently has no `filters` object,
 *   and chunks have no `language`, `tags`, or business `version` fields.
 *   This node is written so filtering activates automatically the moment
 *   those fields exist upstream — no code change required. Until then,
 *   `filters_applied.requested` will simply be empty and everything passes.
 *
 * NO ranking, NO prompt building, NO LLM calls happen in this node.
 */

const items = $input.all();
const output = [];

// ---- Configuration ----------------------------------------------------
const CONFIG = {
  minChunksRequired: 1,
  // Keys this node knows how to filter on IF present on both the request
  // and the chunk. Extend this list when new metadata fields are added.
  allowedFilterKeys: ['department', 'category', 'document_uuid', 'file_name', 'language', 'tags', 'version'],
};

// ---- Main ---------------------------------------------------------------

for (const item of items) {
  const data = item.json ?? {};

  const searchRequest = data.search_request ?? {};
  const requestMetadata = data.request_metadata ?? {};
  const retrieval = data.retrieval ?? {};
  const retrievalMetrics = data.retrieval_metrics ?? {};
  const retrievalAnalytics = data.retrieval_analytics ?? {};
  const retrievalStatus = data.retrieval_status ?? {};
  const upstreamSearchStatus = data.search_status;

  const validationErrors = [];

  // 1. Upstream status validation
  if (upstreamSearchStatus !== 'ok') {
    validationErrors.push(`Upstream search_status is "${upstreamSearchStatus ?? 'undefined'}", expected "ok".`);
  }
  if (retrievalStatus.status !== 'SUCCESS') {
    validationErrors.push(`Upstream retrieval_status is "${retrievalStatus.status ?? 'undefined'}", expected "SUCCESS".`);
  }

  // 2. Chunk presence validation
  const rawChunks = Array.isArray(retrieval.chunks) ? retrieval.chunks : [];
  if (rawChunks.length < CONFIG.minChunksRequired) {
    validationErrors.push(`No chunks returned by retrieval (found ${rawChunks.length}).`);
  }

  // 3. Threshold re-validation (defense in depth — do not trust upstream
  //    filtering blindly; this also surfaces scoring anomalies such as a
  //    flat, non-discriminating score across all results).
  const threshold = typeof retrievalMetrics.threshold === 'number' ? retrievalMetrics.threshold : null;
  let chunksAboveThreshold = rawChunks;
  if (threshold !== null) {
    chunksAboveThreshold = rawChunks.filter((c) => typeof c.score === 'number' && c.score >= threshold);
    const droppedCount = rawChunks.length - chunksAboveThreshold.length;
    if (droppedCount > 0) {
      validationErrors.push(`${droppedCount} chunk(s) reported by upstream fell below threshold (${threshold}) on re-check.`);
    }
  }

  // 3b. Score variance sanity check — surfaces the "all scores identical"
  // anomaly instead of silently ranking on a dead signal downstream.
  const distinctScores = new Set(chunksAboveThreshold.map((c) => c.score)).size;
  const scoreVarianceWarning =
    chunksAboveThreshold.length > 1 && distinctScores === 1
      ? 'All chunks share an identical similarity score. Vector similarity is not discriminating relevance — verify the embedding/scoring step in Workflow 3 before trusting ranked output.'
      : null;

  // 4. Metadata filtering (only applied if criteria supplied)
  const requestedFilters = {};
  const filtersSource = searchRequest.filters ?? {};
  for (const key of CONFIG.allowedFilterKeys) {
    if (filtersSource[key] !== undefined && filtersSource[key] !== null && filtersSource[key] !== '') {
      requestedFilters[key] = filtersSource[key];
    }
  }

  let filteredChunks = chunksAboveThreshold;
  if (Object.keys(requestedFilters).length > 0) {
    filteredChunks = chunksAboveThreshold.filter((chunk) => {
      return Object.entries(requestedFilters).every(([key, expected]) => {
        const actual = chunk[key];
        if (Array.isArray(expected)) {
          return Array.isArray(actual) ? actual.some((v) => expected.includes(v)) : expected.includes(actual);
        }
        return actual === expected;
      });
    });
  }

  const isValid = validationErrors.length === 0 && filteredChunks.length > 0;

  output.push({
    json: {
      search_request: searchRequest,
      request_metadata: requestMetadata,
      retrieval_metrics: retrievalMetrics,
      retrieval_analytics: retrievalAnalytics,
      validated_chunks: filteredChunks,
      filters_applied: {
        requested: requestedFilters,
        chunks_before_filtering: chunksAboveThreshold.length,
        chunks_after_filtering: filteredChunks.length,
      },
      validation_status: {
        status: isValid ? 'VALID' : 'INVALID',
        errors: validationErrors,
        warnings: scoreVarianceWarning ? [scoreVarianceWarning] : [],
      },
    },
  });
}

return output;

/**
 * Workflow 4 — Vector Retrieval Engine
 * Node 2: Composite Ranking & Diversity Engine
 *
 * Single Responsibility:
 *   - Compute a composite relevance score per chunk using ONLY signals that
 *     actually exist in the current schema.
 *   - Enforce diversity so one document cannot dominate the evidence set.
 *   - Produce ranked_evidence + ranking_analytics. NO prompt building, NO LLM.
 *
 * SCHEMA GAP — READ BEFORE CHANGING WEIGHTS:
 *   The architecture calls for ranking to weigh "document authority" and
 *   "business priority" alongside similarity. Neither field exists anywhere
 *   in the Workflow 1→3 pipeline output (no document_authority_score, no
 *   business_priority tag, no true document "last updated" date — only
 *   received_at, which is ingestion time, and workflow_version, which is a
 *   pipeline version number, not a document version).
 *
 *   Per project standards (never assume fields that don't exist, never
 *   generate placeholder code), these weights are set to 0 and marked
 *   DISABLED below rather than fed fabricated values. Recommendation: add
 *   `document_authority_score` (numeric) and `business_priority_tier`
 *   (enum) to document metadata in Workflow 1 intake. Once present, enable
 *   them here by changing RANKING_WEIGHTS — no other code changes needed.
 */

const items = $input.all();
const output = [];

// ---- Configuration ------------------------------------------------------
const RANKING_WEIGHTS = {
  similarity: 0.70,          // chunk.score — the only true relevance signal today
  sectionStructure: 0.20,    // proxy from section_level + chunk_index (see below)
  ingestionRecency: 0.10,    // proxy from received_at — NOT document freshness
  documentAuthority: 0,      // DISABLED — field does not exist yet
  businessPriority: 0,       // DISABLED — field does not exist yet
};

const DIVERSITY_CONFIG = {
  maxChunksPerDocument: 3,
  enforceDiversity: true,
};

// ---- Helpers --------------------------------------------------------------

function clamp01(n) {
  if (typeof n !== 'number' || Number.isNaN(n)) return 0;
  return Math.min(1, Math.max(0, n));
}

/**
 * Structural importance proxy in [0, 1]. Earlier chunks and higher-level
 * sections (section_level = 1) tend to carry title/purpose/definition
 * content, which is more useful as anchoring context.
 */
function computeSectionStructureScore(chunk) {
  const level = typeof chunk.section_level === 'number' && chunk.section_level > 0 ? chunk.section_level : 1;
  const index = typeof chunk.chunk_index === 'number' ? chunk.chunk_index : 0;
  const total = typeof chunk.total_chunks === 'number' && chunk.total_chunks > 0 ? chunk.total_chunks : 1;

  const levelScore = 1 / level;
  const positionScore = 1 - (index / total);

  return clamp01((levelScore * 0.5) + (positionScore * 0.5));
}

/**
 * Ingestion recency proxy in [0, 1]. Reflects when the chunk was ingested
 * into the pipeline, NOT when the source document was authored or last
 * updated. Treated as a minor, secondary signal only — see weight above.
 */
function computeIngestionRecencyScore(chunk, nowMs) {
  if (!chunk.received_at) return 0.5; // neutral if missing
  const receivedTime = Date.parse(chunk.received_at);
  if (Number.isNaN(receivedTime)) return 0.5;

  const ageDays = Math.max(0, (nowMs - receivedTime) / (1000 * 60 * 60 * 24));
  const HALF_LIFE_DAYS = 180; // tune per business needs
  return clamp01(Math.pow(0.5, ageDays / HALF_LIFE_DAYS));
}

function computeCompositeScore(chunk, nowMs) {
  const similarity = clamp01(typeof chunk.score === 'number' ? chunk.score : 0);
  const sectionStructure = computeSectionStructureScore(chunk);
  const ingestionRecency = computeIngestionRecencyScore(chunk, nowMs);

  const breakdown = {
    similarity,
    sectionStructure,
    ingestionRecency,
    documentAuthority: null, // disabled — no data
    businessPriority: null,  // disabled — no data
  };

  const compositeScore =
    (similarity * RANKING_WEIGHTS.similarity) +
    (sectionStructure * RANKING_WEIGHTS.sectionStructure) +
    (ingestionRecency * RANKING_WEIGHTS.ingestionRecency);

  return { compositeScore: clamp01(compositeScore), breakdown };
}

/**
 * Diversity enforcement: sort by composite score, then greedily select
 * while respecting a per-document cap. If the cap would leave fewer chunks
 * than are available, backfill from the overflow so evidence is never
 * discarded unnecessarily in a small corpus.
 */
function applyDiversity(scoredChunks, config) {
  const sorted = [...scoredChunks].sort((a, b) => b.compositeScore - a.compositeScore);

  if (!config.enforceDiversity) {
    return { selected: sorted, diversityCapped: 0 };
  }

  const perDocCount = new Map();
  const selected = [];
  const overflow = [];

  for (const chunk of sorted) {
    const docId = chunk.document_uuid ?? 'unknown';
    const count = perDocCount.get(docId) ?? 0;
    if (count < config.maxChunksPerDocument) {
      selected.push(chunk);
      perDocCount.set(docId, count + 1);
    } else {
      overflow.push(chunk);
    }
  }

  return { selected: [...selected, ...overflow], diversityCapped: overflow.length };
}

// ---- Main -------------------------------------------------------------------

for (const item of items) {
  const data = item.json ?? {};
  const validatedChunks = Array.isArray(data.validated_chunks) ? data.validated_chunks : [];
  const validationStatus = data.validation_status ?? {};

  if (validationStatus.status !== 'VALID' || validatedChunks.length === 0) {
    output.push({
      json: {
        search_request: data.search_request ?? {},
        request_metadata: data.request_metadata ?? {},
        retrieval_analytics: data.retrieval_analytics ?? {},
        ranked_evidence: [],
        ranking_analytics: {
          documents_represented: 0,
          score_distribution: null,
          diversity_capped_count: 0,
          weights_used: RANKING_WEIGHTS,
        },
        status: {
          status: 'FAILURE',
          reason: validationStatus.errors?.length
            ? validationStatus.errors.join(' ')
            : 'No validated chunks available for ranking.',
        },
      },
    });
    continue;
  }

  const nowMs = Date.now();

  const scored = validatedChunks.map((chunk) => {
    const { compositeScore, breakdown } = computeCompositeScore(chunk, nowMs);
    return { ...chunk, compositeScore, scoreBreakdown: breakdown };
  });

  const { selected, diversityCapped } = applyDiversity(scored, DIVERSITY_CONFIG);

  const rankedEvidence = selected.map((chunk, idx) => ({
    rank: idx + 1,
    final_score: Number(chunk.compositeScore.toFixed(4)),
    score_breakdown: chunk.scoreBreakdown,
    chunk_uuid: chunk.chunk_uuid,
    chunk_id: chunk.chunk_id,
    document_uuid: chunk.document_uuid,
    file_name: chunk.file_name,
    section_title: chunk.section_title,
    section_level: chunk.section_level,
    category: chunk.category,
    department: chunk.department,
    text: chunk.text,
    original_similarity_score: chunk.score,
    // Added for Workflow 5 adjacency detection (merge adjacent chunks
    // from the same document/section). Without these, Workflow 5 cannot
    // tell that two chunks are consecutive parts of the same source text.
    chunk_index: chunk.chunk_index,
    total_chunks: chunk.total_chunks,
    chunk_start: chunk.chunk_start,
    chunk_end: chunk.chunk_end,
  }));

  const scores = rankedEvidence.map((c) => c.final_score);
  const documentsRepresented = new Set(rankedEvidence.map((c) => c.document_uuid)).size;

  output.push({
    json: {
      search_request: data.search_request ?? {},
      request_metadata: data.request_metadata ?? {},
      retrieval_analytics: data.retrieval_analytics ?? {},
      ranked_evidence: rankedEvidence,
      ranking_analytics: {
        total_ranked: rankedEvidence.length,
        documents_represented: documentsRepresented,
        score_distribution: {
          max: Math.max(...scores),
          min: Math.min(...scores),
          avg: Number((scores.reduce((a, b) => a + b, 0) / scores.length).toFixed(4)),
        },
        diversity_capped_count: diversityCapped,
        weights_used: RANKING_WEIGHTS,
      },
      status: { status: 'SUCCESS', reason: 'Ranking and diversity enforcement completed.' },
    },
  });
}

return output;

/**
 * Workflow 5 — Context Construction Engine
 * Node 1: Query Complexity Classification & Budget Allocation
 *
 * Single Responsibility:
 *   - Classify the query as SIMPLE / MEDIUM / COMPLEX using a text heuristic.
 *   - Translate that classification into a chunk budget and token budget for
 *     Node 2 to enforce.
 *
 * SCHEMA GAP / KNOWN LIMITATION:
 *   Classification here is a keyword + structure heuristic, not true NLP
 *   intent detection. It will misclassify edge cases (e.g. a short query
 *   that is nonetheless conceptually complex, or a long query that is
 *   simple). This is intentional — a real classifier would need either an
 *   LLM call (which the architecture explicitly forbids before Workflow 6)
 *   or a trained model neither of which exists yet. Treat this as a
 *   reasonable default, not a solved problem; tune COMPLEXITY_RULES below
 *   as real query patterns are observed in production.
 *
 * NO prompt building, NO LLM calls happen in this node.
 */

const items = $input.all();
const output = [];

// ---- Configuration --------------------------------------------------------

const COMPLEXITY_RULES = {
  // Words/phrases that strongly indicate a comparative or multi-part query.
  comparisonMarkers: [
    'compare', 'comparison', ' vs ', ' vs.', 'versus',
    'difference between', 'differences between',
    'which is better', 'pros and cons', 'better than',
  ],
  // Conjunctions that often join two distinct sub-questions.
  multiPartMarkers: [' and how ', ' and what ', ' and why ', ' as well as '],
  simpleMaxWordCount: 7,
  mediumMaxWordCount: 14,
};

const BUDGET_BY_COMPLEXITY = {
  SIMPLE: { minChunks: 3, maxChunks: 5 },
  MEDIUM: { minChunks: 5, maxChunks: 8 },
  COMPLEX: { minChunks: 8, maxChunks: 12 },
};

// Fixed target regardless of complexity, per architecture spec ("Target
// 3500 tokens"). If this should scale with complexity later, make this a
// map instead of a constant — no other code changes would be needed.
const TOKEN_BUDGET_TARGET = 3500;

// ---- Helpers ----------------------------------------------------------

function countWords(text) {
  if (!text || typeof text !== 'string') return 0;
  return text.trim().split(/\s+/).filter(Boolean).length;
}

function containsAny(haystack, needles) {
  const lower = haystack.toLowerCase();
  return needles.some((needle) => lower.includes(needle));
}

/**
 * Classifies query complexity using word count + structural markers.
 * Returns { level, indicators } where indicators explains *why*, useful
 * for debugging misclassifications later (surfaced in analytics, not logic).
 */
function classifyComplexity(query) {
  const q = (query ?? '').toLowerCase().trim();
  const wordCount = countWords(q);
  const indicators = [];

  const hasComparison = containsAny(q, COMPLEXITY_RULES.comparisonMarkers);
  const hasMultiPart = containsAny(q, COMPLEXITY_RULES.multiPartMarkers);
  const questionMarkCount = (q.match(/\?/g) ?? []).length;

  if (hasComparison) indicators.push('comparison_marker');
  if (hasMultiPart) indicators.push('multi_part_marker');
  if (questionMarkCount > 1) indicators.push('multiple_question_marks');
  indicators.push(`word_count:${wordCount}`);

  if (hasComparison || hasMultiPart || questionMarkCount > 1) {
    return { level: 'COMPLEX', indicators };
  }
  if (wordCount > COMPLEXITY_RULES.mediumMaxWordCount) {
    return { level: 'COMPLEX', indicators };
  }
  if (wordCount > COMPLEXITY_RULES.simpleMaxWordCount) {
    return { level: 'MEDIUM', indicators };
  }
  return { level: 'SIMPLE', indicators };
}

// ---- Main -------------------------------------------------------------

for (const item of items) {
  const data = item.json ?? {};

  const searchRequest = data.search_request ?? {};
  const rankedEvidence = Array.isArray(data.ranked_evidence) ? data.ranked_evidence : [];
  const retrievalAnalytics = data.retrieval_analytics ?? {};
  const upstreamStatus = data.status ?? {};

  // Defensive: if the upstream ranking step failed, don't attempt
  // classification — pass the failure through unchanged.
  if (upstreamStatus.status !== 'SUCCESS' || rankedEvidence.length === 0) {
    output.push({
      json: {
        search_request: searchRequest,
        ranked_evidence: rankedEvidence,
        retrieval_analytics: retrievalAnalytics,
        query_complexity: null,
        status: {
          status: 'FAILURE',
          reason: 'No ranked evidence available for context construction.',
        },
      },
    });
    continue;
  }

  const queryText = searchRequest.normalized_query ?? searchRequest.query ?? '';
  const { level, indicators } = classifyComplexity(queryText);
  const budget = BUDGET_BY_COMPLEXITY[level];

  output.push({
    json: {
      search_request: searchRequest,
      ranked_evidence: rankedEvidence,
      retrieval_analytics: retrievalAnalytics,
      query_complexity: {
        level,
        indicators,
        chunk_budget: budget,
        token_budget: TOKEN_BUDGET_TARGET,
      },
      status: { status: 'SUCCESS', reason: 'Query complexity classified.' },
    },
  });
}

return output;

/**
 * Workflow 5 — Context Construction Engine
 * Node 2: Dedup, Merge, Compress, Budget Enforcement & Ordering
 *
 * Single Responsibility:
 *   - Remove duplicate chunks.
 *   - Merge adjacent chunks (same document, consecutive chunk_index).
 *   - Compress merged text (strip repeated headings/whitespace).
 *   - Enforce the chunk + token budgets from Node 1.
 *   - Order surviving chunks into primary / supporting / background tiers.
 *   - Emit ONLY what Workflow 6 needs — no full retrieval/ranking payload.
 *
 * TOKEN ESTIMATION — SCALABILITY DECISION:
 *   No real Gemini tokenizer is used here, by design. A "real" tokenizer
 *   (e.g. a GPT BPE library) would still be an approximation for Gemini's
 *   own SentencePiece-based tokenizer, would add an npm dependency to
 *   maintain in the Docker n8n environment, and would need updating if the
 *   embedding/generation model changes. Instead this uses a character-based
 *   estimate (~4 characters per token for English/technical text, a widely
 *   used and fairly stable approximation across modern tokenizers) with a
 *   safety margin applied via TOKEN_ESTIMATE_SAFETY_FACTOR. This is
 *   portable, dependency-free, deterministic, and "good enough" given even
 *   a real tokenizer wouldn't be exact for this specific model. If token
 *   overruns are ever observed in practice, tighten
 *   TOKEN_ESTIMATE_SAFETY_FACTOR rather than reaching for a heavier
 *   dependency first.
 *
 * NO prompt building, NO LLM calls happen in this node.
 */

const items = $input.all();
const output = [];

// ---- Configuration ------------------------------------------------------

const CHARS_PER_TOKEN_ESTIMATE = 4;
// Inflate the raw estimate by this factor before comparing to budget, to
// leave headroom for tokenizer variance and the prompt scaffolding
// Workflow 6 will add around this context.
const TOKEN_ESTIMATE_SAFETY_FACTOR = 1.15;

// Tier boundaries as a fraction of the score range within the *selected*
// chunk set (not the full corpus) — top third = primary, etc.
const TIER_BOUNDARIES = { primary: 0.667, supporting: 0.333 };

// ---- Helpers --------------------------------------------------------------

function estimateTokens(text) {
  if (!text) return 0;
  const rawEstimate = text.length / CHARS_PER_TOKEN_ESTIMATE;
  return Math.ceil(rawEstimate * TOKEN_ESTIMATE_SAFETY_FACTOR);
}

/**
 * Compresses merged text: collapses 3+ newlines to 2, strips leading/
 * trailing whitespace per line, removes an exact duplicate of the section
 * title if it appears again later in the merged body (common when merging
 * chunks whose text repeats the heading).
 */
function compressText(text, sectionTitle) {
  if (!text) return '';
  let result = text.replace(/[ \t]+\n/g, '\n').replace(/\n{3,}/g, '\n\n').trim();

  if (sectionTitle) {
    const titleIndex = result.indexOf(sectionTitle);
    if (titleIndex !== -1) {
      const secondOccurrence = result.indexOf(sectionTitle, titleIndex + sectionTitle.length);
      if (secondOccurrence !== -1) {
        result =
          result.slice(0, secondOccurrence) +
          result.slice(secondOccurrence + sectionTitle.length);
        result = result.replace(/\n{3,}/g, '\n\n').trim();
      }
    }
  }
  return result;
}

/**
 * Groups chunks by document_uuid, sorts each group by chunk_index, and
 * merges runs of consecutive chunk_index values into single merged chunks.
 * Adjacency is determined strictly by chunk_index (see prior discussion —
 * chunk_start/chunk_end are per-chunk-relative, not document-absolute, so
 * they cannot be used for contiguity detection).
 */
function mergeAdjacentChunks(chunks) {
  const byDocument = new Map();
  for (const chunk of chunks) {
    const key = chunk.document_uuid ?? 'unknown';
    if (!byDocument.has(key)) byDocument.set(key, []);
    byDocument.get(key).push(chunk);
  }

  const merged = [];
  for (const group of byDocument.values()) {
    group.sort((a, b) => (a.chunk_index ?? 0) - (b.chunk_index ?? 0));

    let current = null;
    for (const chunk of group) {
      const isAdjacent =
        current !== null &&
        typeof chunk.chunk_index === 'number' &&
        typeof current.lastChunkIndex === 'number' &&
        chunk.chunk_index === current.lastChunkIndex + 1;

      if (isAdjacent) {
        current.text = `${current.text}\n\n${chunk.text ?? ''}`.trim();
        current.final_score = Math.max(current.final_score, chunk.final_score ?? 0);
        current.source_chunk_uuids.push(chunk.chunk_uuid);
        current.source_chunk_ids.push(chunk.chunk_id);
        current.lastChunkIndex = chunk.chunk_index;
      } else {
        if (current) merged.push(current);
        current = {
          ...chunk,
          text: chunk.text ?? '',
          source_chunk_uuids: [chunk.chunk_uuid],
          source_chunk_ids: [chunk.chunk_id],
          lastChunkIndex: chunk.chunk_index,
        };
      }
    }
    if (current) merged.push(current);
  }

  return merged;
}

/**
 * Selects chunks under the chunk + token budgets. Assumes chunks are
 * pre-sorted descending by final_score. Stops adding once either budget
 * would be exceeded, always keeping at least one chunk if any exist.
 */
function applyBudgets(chunks, chunkBudget, tokenBudget) {
  const selected = [];
  let tokenTotal = 0;

  for (const chunk of chunks) {
    if (selected.length >= chunkBudget.maxChunks) break;

    const chunkTokens = estimateTokens(chunk.text);
    const wouldExceedTokenBudget = tokenTotal + chunkTokens > tokenBudget;

    if (wouldExceedTokenBudget && selected.length > 0) {
      // Stop here — adding this chunk would blow the token budget, and we
      // already have at least one chunk selected.
      break;
    }

    selected.push(chunk);
    tokenTotal += chunkTokens;
  }

  return { selected, tokenTotal };
}

/**
 * Assigns primary/supporting/background tiers based on each chunk's
 * final_score position within the selected set's own score range.
 */
function assignTiers(chunks) {
  if (chunks.length === 0) return chunks;

  const scores = chunks.map((c) => c.final_score ?? 0);
  const max = Math.max(...scores);
  const min = Math.min(...scores);
  const range = max - min;

  return chunks.map((chunk) => {
    const normalized = range === 0 ? 1 : (chunk.final_score - min) / range;
    let tier;
    if (normalized >= TIER_BOUNDARIES.primary) tier = 'primary';
    else if (normalized >= TIER_BOUNDARIES.supporting) tier = 'supporting';
    else tier = 'background';
    return { ...chunk, tier };
  });
}

const TIER_ORDER = { primary: 0, supporting: 1, background: 2 };

// ---- Main -----------------------------------------------------------------

for (const item of items) {
  const data = item.json ?? {};
  const searchRequest = data.search_request ?? {};
  const rankedEvidence = Array.isArray(data.ranked_evidence) ? data.ranked_evidence : [];
  const queryComplexity = data.query_complexity;
  const upstreamStatus = data.status ?? {};

  if (upstreamStatus.status !== 'SUCCESS' || !queryComplexity || rankedEvidence.length === 0) {
    output.push({
      json: {
        context_request: { query: searchRequest.normalized_query ?? searchRequest.query ?? null },
        optimized_context: '',
        optimized_chunks: [],
        source_map: [],
        analytics: { total_selected: 0, token_estimate: 0 },
        status: {
          status: 'FAILURE',
          reason: upstreamStatus.reason ?? 'No query complexity or ranked evidence available.',
        },
      },
    });
    continue;
  }

  // 1. Dedup by chunk_uuid.
  const seen = new Set();
  const deduped = rankedEvidence.filter((chunk) => {
    if (!chunk.chunk_uuid || seen.has(chunk.chunk_uuid)) return false;
    seen.add(chunk.chunk_uuid);
    return true;
  });

  // 2. Merge adjacent chunks within the same document.
  const merged = mergeAdjacentChunks(deduped);

  // 3. Compress merged text.
  for (const chunk of merged) {
    chunk.text = compressText(chunk.text, chunk.section_title);
  }

  // 4. Re-sort by score (merging can change effective ranking) and apply budgets.
  merged.sort((a, b) => (b.final_score ?? 0) - (a.final_score ?? 0));
  const { selected, tokenTotal } = applyBudgets(
    merged,
    queryComplexity.chunk_budget,
    queryComplexity.token_budget
  );

  // 5. Assign tiers, then order primary -> supporting -> background.
  const tiered = assignTiers(selected);
  tiered.sort((a, b) => TIER_ORDER[a.tier] - TIER_ORDER[b.tier] || (b.final_score - a.final_score));

  // 6. Build the assembled context text, grouped by tier with headers.
  const tierLabels = { primary: 'Primary Evidence', supporting: 'Supporting Evidence', background: 'Background Evidence' };
  const sections = [];
  for (const tierKey of ['primary', 'supporting', 'background']) {
    const chunksInTier = tiered.filter((c) => c.tier === tierKey);
    if (chunksInTier.length === 0) continue;
    const body = chunksInTier
      .map((c) => `### ${c.section_title ?? c.file_name ?? 'Untitled'}\n${c.text}`)
      .join('\n\n');
    sections.push(`## ${tierLabels[tierKey]}\n\n${body}`);
  }
  const optimizedContext = sections.join('\n\n---\n\n');

  // 7. Build optimized_chunks (structured) and source_map (attribution only).
  const optimizedChunks = tiered.map((c, idx) => ({
    order: idx + 1,
    tier: c.tier,
    text: c.text,
    final_score: c.final_score,
    document_uuid: c.document_uuid,
    file_name: c.file_name,
    section_title: c.section_title,
  }));

  const sourceMap = tiered.map((c) => ({
    chunk_uuids: c.source_chunk_uuids,
    chunk_ids: c.source_chunk_ids,
    document_uuid: c.document_uuid,
    file_name: c.file_name,
    section_title: c.section_title,
    final_score: c.final_score,
  }));

  output.push({
    json: {
      search_request: $json.search_request,
      context_request: {
        query: searchRequest.normalized_query ?? searchRequest.query ?? null,
        complexity: queryComplexity.level,
        chunk_budget: queryComplexity.chunk_budget,
        token_budget: queryComplexity.token_budget,
      },
      optimized_context: optimizedContext,
      optimized_chunks: optimizedChunks,
      source_map: sourceMap,
      analytics: {
        chunks_before_dedup: rankedEvidence.length,
        chunks_after_dedup: deduped.length,
        chunks_after_merge: merged.length,
        chunks_selected: selected.length,
        token_estimate: tokenTotal,
        token_budget: queryComplexity.token_budget,
        tier_counts: {
          primary: tiered.filter((c) => c.tier === 'primary').length,
          supporting: tiered.filter((c) => c.tier === 'supporting').length,
          background: tiered.filter((c) => c.tier === 'background').length,
        },
      },
      status: { status: 'SUCCESS', reason: 'Context constructed within budget.' },
    },
  });
}

return output;

