parameters.jsCode:
/**
 * Workflow 6 — AI Response Generation
 * Node A: Prompt Builder
 *
 * Single Responsibility:
 *   - Build the system prompt and user prompt text that feed into the
 *     native "Basic LLM Chain" node (Google Gemini Chat Model + Structured
 *     Output Parser attached).
 *   - This node does NOT call Gemini itself — that happens in the Basic
 *     LLM Chain node immediately downstream. This is the only workflow
 *     permitted to reach an LLM, and it does so via the native node, not
 *     an HTTP call from Code.
 *
 * WIRING NOTE:
 *   In the Basic LLM Chain node, set:
 *     - "Text" (user prompt) field to: {{ $json.userPrompt }}
 *     - "System Message" (if your n8n version exposes it under Options)
 *       to: {{ $json.systemPrompt }}
 *   If your version of the node doesn't expose a separate System Message
 *   field, prepend systemPrompt to userPrompt manually — a fallback field
 *   `combinedPrompt` is provided below for that case.
 *
 * NO Gemini call happens in this node.
 */

const items = $input.all();
const output = [];

// ---- Configuration ------------------------------------------------------

const SYSTEM_PROMPT = `You are an internal IT knowledge assistant. Answer the user's question using ONLY the context provided below. Follow these rules strictly:

1. Base your answer entirely on the provided context. Do not use outside knowledge, even if you are confident it is correct.
2. If the context does not contain enough information to answer, say so explicitly rather than guessing.
3. Every factual claim in your answer must be traceable to one of the provided source sections. Cite each source you use by its exact file_name and section_title as given in the context — do not invent, paraphrase, or guess at source names.
4. Do not cite a source you did not actually use to support a specific claim.
5. Keep the answer concise and directly responsive to the question. Do not repeat the full context verbatim.
6. Respond ONLY in the structured JSON format defined by the output parser. Do not include any text outside that structure.
7. Use customer name in greating.
8. greating must be short and professional.
9. use company name if not "Unknown" when needed`;

// ---- Main -----------------------------------------------------------------

for (const item of items) {
  const data = item.json ?? {};

  const contextRequest = data.context_request ?? {};
  const optimizedContext = data.optimized_context ?? '';
  const optimizedChunks = Array.isArray(data.optimized_chunks) ? data.optimized_chunks : [];
  const sourceMap = Array.isArray(data.source_map) ? data.source_map : [];
  const analytics = data.analytics ?? {};
  const upstreamStatus = data.status ?? {};

  if (upstreamStatus.status !== 'SUCCESS' || optimizedChunks.length === 0) {
    output.push({
      json: {
        systemPrompt: SYSTEM_PROMPT,
        userPrompt: '',
        combinedPrompt: '',
        query: contextRequest.query ?? null,
        source_map: sourceMap,
        optimized_chunks: optimizedChunks,
        analytics,
        status: {
          status: 'FAILURE',
          reason: upstreamStatus.reason ?? 'No optimized context available to build a prompt from.',
        },
      },
    });
    continue;
  }

  // Build the list of valid, citable sources explicitly, so the model has
  // an unambiguous menu to choose from rather than inferring names from
  // prose. This directly supports citation validation downstream — any
  // citation NOT drawn from this exact list is flagged as invalid later.
  const citableSourcesList = sourceMap
    .map((s, idx) => `${idx + 1}. file_name: "${s.file_name}" | section_title: "${s.section_title}"`)
    .join('\n');

  const userPrompt = `Question: ${contextRequest.query ?? ''}

Context:
${optimizedContext}

Citable sources (use these exact file_name and section_title values in your citations, and no others):
${citableSourcesList}

Customer Name: ${$json.search_request.customer_name}

Company Name: ${$json.search_request.company}
`;

  const combinedPrompt = `${SYSTEM_PROMPT}\n\n${userPrompt}`;

  output.push({
    json: {
      systemPrompt: SYSTEM_PROMPT,
      userPrompt,
      combinedPrompt,
      query: contextRequest.query ?? null,
      source_map: sourceMap,
      optimized_chunks: optimizedChunks,
      analytics,
      status: { status: 'SUCCESS', reason: 'Prompt built.' },
    },
  });
}

return output;

/**
 * Workflow 6 — AI Response Generation
 * Node B: Citation Validation & Confidence Scoring (post-processing)
 *
 * Single Responsibility:
 *   - Runs AFTER the native Basic LLM Chain node (Gemini + Structured
 *     Output Parser). Takes its parsed JSON output and:
 *       1. Validates every citation against source_map (catches
 *          hallucinated/invented sources — NOT a fact-check of content).
 *       2. Computes confidence from the RETRIEVAL signal already in hand
 *          (top chunk score, tier composition) — no second LLM call,
 *          since self-reported LLM confidence is unreliable and a
 *          verification call would double latency/cost for marginal gain.
 *       3. Assembles the final output: draft answer, validated citations,
 *          confidence, reasoning metadata, token usage, model metadata.
 *
 * WIRING NOTE — VERIFY BEFORE RELYING ON THIS:
 *   The exact field path for the Basic LLM Chain node's parsed output and
 *   token usage varies by n8n/LangChain node version. Common locations:
 *     - Parsed structured output: $json.output  (sometimes $json directly,
 *       or nested under a model-specific key — check your node's actual
 *       output in the execution panel before trusting llmOutput below)
 *     - Token usage: $json.tokenUsage / $json.usage_metadata / absent
 *       entirely on some versions (Gemini nodes don't always surface it)
 *   Adjust the extraction lines marked below to match what you actually see.
 *
 * This is the ONLY workflow permitted to have called Gemini, and that call
 * already happened upstream in the native node — this node does not call
 * any LLM itself.
 */

const items = $input.all();
const output = [];

// ---- Configuration ------------------------------------------------------

// Confidence bands for human-readable labeling alongside the numeric score.
const CONFIDENCE_BANDS = [
  { min: 0.75, label: 'HIGH' },
  { min: 0.5, label: 'MEDIUM' },
  { min: 0, label: 'LOW' },
];

// Multiplier applied to top-chunk score when NO primary-tier chunk was
// used as evidence — answer is grounded in weaker (background-tier)
// context, so confidence should reflect that even if the raw score is
// reasonable in isolation.
const NO_PRIMARY_TIER_PENALTY = 0.7;

// ---- Helpers --------------------------------------------------------------

function normalizeSourceKey(fileName, sectionTitle) {
  return `${(fileName ?? '').trim().toLowerCase()}::${(sectionTitle ?? '').trim().toLowerCase()}`;
}

/**
 * Validates each citation the model returned against the known source_map.
 * A citation is valid only if its (file_name, section_title) pair exactly
 * matches an entry the model was actually given — this catches invented
 * or misattributed sources, not whether the cited claim is itself correct.
 */
function validateCitations(citations, sourceMap) {
  const validKeys = new Set(
    sourceMap.map((s) => normalizeSourceKey(s.file_name, s.section_title))
  );

  const validated = citations.map((citation) => {
    const key = normalizeSourceKey(citation.file_name, citation.section_title);
    return {
      file_name: citation.file_name,
      section_title: citation.section_title,
      is_valid: validKeys.has(key),
    };
  });

  const invalidCount = validated.filter((c) => !c.is_valid).length;
  return { validated, invalidCount };
}

/**
 * Confidence derived entirely from retrieval signal already computed in
 * Workflow 4/5 — no LLM self-report, no second LLM call. Base is the
 * highest final_score among chunks actually selected into context; this
 * is penalized if none of those chunks were primary-tier (i.e. the answer
 * leans on weaker evidence) and if the model itself flagged insufficient
 * context.
 */
function computeConfidence(optimizedChunks, insufficientContext) {
  if (!optimizedChunks || optimizedChunks.length === 0) {
    return { score: 0, level: 'LOW', basis: 'No context chunks were available.' };
  }

  const topScore = Math.max(...optimizedChunks.map((c) => c.final_score ?? 0));
  const hasPrimaryTier = optimizedChunks.some((c) => c.tier === 'primary');

  let score = topScore;
  const basisNotes = [`top_chunk_score=${topScore.toFixed(4)}`];

  if (!hasPrimaryTier) {
    score *= NO_PRIMARY_TIER_PENALTY;
    basisNotes.push(`no_primary_tier_chunk_used (x${NO_PRIMARY_TIER_PENALTY})`);
  }

  if (insufficientContext) {
    score *= 0.5;
    basisNotes.push('model_flagged_insufficient_context (x0.5)');
  }

  score = Math.min(1, Math.max(0, score));
  const level = CONFIDENCE_BANDS.find((band) => score >= band.min).label;

  return { score: Number(score.toFixed(4)), level, basis: basisNotes.join('; ') };
}

// ---- Main -------------------------------------------------------------

for (const item of items) {
  const data = item.json ?? {};

  // --- ADJUST HERE if your Basic LLM Chain node's output field differs ---
  const llmOutput = data.output ?? data;
  // -------------------------------------------------------------------

  const sourceMap = Array.isArray(data.source_map) ? data.source_map : [];
  const analytics = data.analytics ?? {};
  const optimizedChunksFromUpstream = Array.isArray(data.optimized_chunks) ? data.optimized_chunks : [];

  const answer = llmOutput?.answer;
  const rawCitations = Array.isArray(llmOutput?.citations) ? llmOutput.citations : [];
  const insufficientContext = llmOutput?.insufficient_context === true;

  if (!answer) {
    output.push({
      json: {
        draft_answer: null,
        citations: [],
        confidence: { score: 0, level: 'LOW', basis: 'No answer returned by model.' },
        reasoning_metadata: { insufficient_context: true, citation_validation: null },
        token_usage: data.analytics.token_estimate ?? data.usage_metadata ?? null,
        model_metadata: { model: data.model ?? 'gemini', source: 'Basic LLM Chain' },
        status: { status: 'FAILURE', reason: 'Model did not return a parsable answer.' },
      },
    });
    continue;
  }

  const { validated, invalidCount } = validateCitations(rawCitations, sourceMap);
  const confidence = computeConfidence(optimizedChunksFromUpstream, insufficientContext);

  output.push({
    json: {
      draft_answer: answer,
      citations: validated,
      source_map:data.source_map,
      confidence,
      reasoning_metadata: {
        insufficient_context: insufficientContext,
        citation_validation: {
          total_citations: validated.length,
          invalid_citations: invalidCount,
        },
      },
      // --- ADJUST HERE if token usage lives at a different path ---
      token_usage: data.analytics.token_estimate  ?? data.usage_metadata ?? null,
      model_metadata: {
        model: data.model ?? 'gemini',
        source: 'Basic LLM Chain',
      },
      status: { status: 'SUCCESS', reason: 'Response validated and confidence scored.' },
    },
  });
}

return output;

/**
 * Workflow 7 — Response Formatting
 *
 * Single Responsibility:
 *   - Convert Workflow 6's raw AI response payload into the final shape
 *     the client (Support Agent UI, chat widget, etc.) actually consumes.
 *   - NO AI calls, NO prompt building — purely presentational reshaping.
 *
 * Responsibilities per architecture spec:
 *   - Answer
 *   - Sources
 *   - Confidence
 *   - Related documents
 *   - Suggested follow-up questions
 *
 * DESIGN NOTE — "Suggested follow-up questions":
 *   Generating genuinely useful follow-up questions well usually needs an
 *   LLM call, which this workflow is explicitly forbidden from making.
 *   Rather than fabricate a fake "smart" feature, this node derives
 *   follow-ups deterministically from the OTHER documents that were
 *   retrieved but not cited (e.g. if the VPN guide was retrieved but not
 *   used in the answer, suggest a follow-up about VPN access). This is a
 *   simple, honest heuristic — not a substitute for an LLM-generated
 *   suggestion — and is skipped entirely if there's nothing to derive it
 *   from, rather than inventing generic filler questions.
 */

const items = $input.all();
const output = [];

// ---- Configuration ------------------------------------------------------

const MAX_RELATED_DOCUMENTS = 3;
const MAX_FOLLOWUP_QUESTIONS = 3;

// ---- Helpers --------------------------------------------------------------

/**
 * Builds a plain-language follow-up question from a document's section
 * title. Deliberately simple templating, not NLP — this is a fallback
 * heuristic, not a generated suggestion.
 */
function toFollowUpQuestion(sectionTitle, fileName) {
  const label = sectionTitle || fileName || 'this topic';
  return `Would you like more information about "${label}"?`;
}

/**
 * Related documents: distinct source documents from source_map that were
 * retrieved as context but were NOT among the validated citations actually
 * used in the answer. This surfaces adjacent, possibly-useful material
 * without claiming the model recommended it.
 */
function deriveRelatedDocuments(sourceMap, citedFileNames) {
  const seen = new Set();
  const related = [];

  for (const source of sourceMap) {
    const key = source.document_uuid;
    if (!key || seen.has(key) || citedFileNames.has(key)) continue;
    seen.add(key);
    related.push({
      file_name: source.file_name,
      section_title: source.section_title,
    });
    if (related.length >= MAX_RELATED_DOCUMENTS) break;
  }

  return related;
}

// ---- Main -------------------------------------------------------------

for (const item of items) {
  const data = item.json ?? {};

  const draftAnswer = data.draft_answer;
  const citations = Array.isArray(data.citations) ? data.citations : [];
  const confidence = data.confidence ?? { score: 0, level: 'LOW', basis: 'Unknown.' };
  const upstreamStatus = data.status ?? {};

  if (upstreamStatus.status !== 'SUCCESS' || !draftAnswer) {
    output.push({
      json: {
        answer: null,
        sources: [],
        confidence: { level: 'LOW', score: 0 },
        related_documents: [],
        suggested_followups: [],
        status: {
          status: 'FAILURE',
          reason: upstreamStatus.reason ?? 'No answer available to format.',
        },
      },
    });
    continue;
  }

  // Sources shown to the user: only VALID citations. Invalid/hallucinated
  // citations caught in Workflow 6 are never surfaced to the client.
  const validCitations = citations.filter((c) => c.is_valid !== false);
  const noUsefulAnswer = confidence.score === 0 || validCitations.length === 0;
  const sources = validCitations.map((c) => ({
    file_name: c.file_name,
    section_title: c.section_title,
  }));

  const citedFileNames = new Set(sources.map((s) => s.file_name));

  // source_map (full retrieved set) may not be present on this node's
  // input depending on what Workflow 6 passes through — guard accordingly.
  const sourceMap = Array.isArray(data.source_map) ? data.source_map : [];
  /**

const relatedDocuments = deriveRelatedDocuments(sourceMap, citedFileNames);

  const suggestedFollowups = relatedDocuments
    .slice(0, MAX_FOLLOWUP_QUESTIONS)
    .map((doc) => toFollowUpQuestion(doc.section_title, doc.file_name));
**/
 const relatedDocuments = noUsefulAnswer ? [] : deriveRelatedDocuments(sourceMap, citedFileNames);
  const suggestedFollowups = noUsefulAnswer ? [] : relatedDocuments.slice(0, MAX_FOLLOWUP_QUESTIONS).map((doc) => toFollowUpQuestion(doc.section_title, doc.file_name));   

  output.push({
    json: {
      answer: draftAnswer,
      sources,
      confidence: { level: confidence.level, score: confidence.score },
      related_documents: relatedDocuments,
      suggested_followups: suggestedFollowups,
      status: { status: 'SUCCESS', reason: 'Response formatted for client delivery.' },
    },
  });
}

return output;

/**
 * Workflow 8 — Logging & Analytics
 *
 * Single Responsibility:
 *   - Aggregate a complete audit record for this query across every stage
 *     of the pipeline (Workflows 3-7) into one flat log entry, ready to be
 *     written to a persistence layer (Postgres/Mongo/Sheets/HTTP — attach
 *     whichever storage node your infra uses AFTER this Code node; this
 *     node only ASSEMBLES the record, it does not store it).
 *
 * CRITICAL WIRING NOTE — same cross-node data loss as Workflow 6 Node B:
 *   By this point in the chain, several nodes (the Basic LLM Chain node
 *   especially) have already replaced the item JSON and dropped fields
 *   from earlier stages. This node does NOT rely on $json for most of its
 *   data — it pulls directly from each stage BY NAME using $('Node Name').
 *   You MUST update the *_NODE_NAME constants below to match the EXACT
 *   node titles as they appear in your n8n canvas (case and spacing must
 *   match exactly, or $() will throw a reference error at runtime).
 *
 * WHAT THIS NODE DOES NOT DO:
 *   - Does not store the record anywhere. Attach a storage node after this
 *     one (Postgres, MongoDB, Google Sheets, or an HTTP Request to your
 *     own logging API all work — pick based on your existing infra).
 *   - Does not capture user_feedback. Feedback (thumbs up/down, corrections)
 *     arrives asynchronously, typically via a separate webhook after the
 *     response is shown to the user. That workflow should UPDATE this
 *     same log record by request_id, not create a new one — out of scope
 *     for this node, which only handles the initial write.
 *   - Does not compute real dollar cost unless token_usage is actually
 *     populated. Given Workflow 6 currently reports token_usage as null
 *     (the Basic LLM Chain node in your version doesn't surface it),
 *     estimated_cost_usd will be null until that's resolved — this node
 *     does not fabricate a cost from an absent token count.
 */

// ---- Configuration — UPDATE THESE to match your actual node titles ------

const QUERY_PROCESSING_NODE_NAME = 'When Executed by Another Workflow'; // Workflow 3 output node
const RETRIEVAL_VALIDATION_NODE_NAME = 'Retrieval Validation & Metadata Filtering'; // Workflow 4 Node 1
const RANKING_NODE_NAME = 'Composite Ranking & Diversity Engine'; // Workflow 4 Node 2
const PROMPT_BUILDER_NODE_NAME = 'Prompt Builder'; // Workflow 6 Node A
const CITATION_VALIDATION_NODE_NAME = 'Citation Validation & Confidence Scoring (post-processing)'; // Workflow 6 Node B

// Rough per-1K-token USD rates, used ONLY if token_usage is ever populated.
// These are placeholders — verify against Gemini's actual current pricing
// before trusting estimated_cost_usd for anything beyond rough tracking.
const COST_PER_1K_TOKENS_USD = { prompt: 0.0, completion: 0.0 };

// ---- Helpers --------------------------------------------------------------

/**
 * Safely reads a named node's first item JSON, returning {} if the node
 * doesn't exist in this execution (e.g. an earlier branch failed and this
 * node never ran) rather than throwing and killing the whole log write.
 */
function safeNodeData(nodeName) {
  try {
    return $(nodeName).item.json ?? {};
  } catch (err) {
    return {};
  }
}

/**
 * Normalizes token_usage into a consistent shape regardless of what the
 * Basic LLM Chain node actually returned. Observed in practice: it
 * sometimes returns a single number (total tokens only), not the
 * {prompt_tokens, completion_tokens} object originally assumed.
 */
function normalizeTokenUsage(tokenUsage) {
  if (tokenUsage == null) {
    return { prompt_tokens: null, completion_tokens: null, total_tokens: null };
  }
  if (typeof tokenUsage === 'number') {
    return { prompt_tokens: null, completion_tokens: null, total_tokens: tokenUsage };
  }
  if (typeof tokenUsage === 'object') {
    const promptTokens = tokenUsage.prompt_tokens ?? tokenUsage.promptTokens ?? null;
    const completionTokens = tokenUsage.completion_tokens ?? tokenUsage.completionTokens ?? null;
    const totalTokens =
      tokenUsage.total_tokens ??
      tokenUsage.totalTokens ??
      (promptTokens != null || completionTokens != null
        ? (promptTokens ?? 0) + (completionTokens ?? 0)
        : null);
    return { prompt_tokens: promptTokens, completion_tokens: completionTokens, total_tokens: totalTokens };
  }
  return { prompt_tokens: null, completion_tokens: null, total_tokens: null };
}

function estimateCost(normalizedTokenUsage) {
  if (!normalizedTokenUsage) return null;
  const { prompt_tokens, completion_tokens, total_tokens } = normalizedTokenUsage;

  if (prompt_tokens != null || completion_tokens != null) {
    const promptCost = ((prompt_tokens ?? 0) / 1000) * COST_PER_1K_TOKENS_USD.prompt;
    const completionCost = ((completion_tokens ?? 0) / 1000) * COST_PER_1K_TOKENS_USD.completion;
    return Number((promptCost + completionCost).toFixed(6));
  }
  if (total_tokens != null) {
    const blendedRate = (COST_PER_1K_TOKENS_USD.prompt + COST_PER_1K_TOKENS_USD.completion) / 2;
    return Number(((total_tokens / 1000) * blendedRate).toFixed(6));
  }
  return null;
}

function computeLatencyMs(receivedAtIso) {
  if (!receivedAtIso) return null;
  const start = Date.parse(receivedAtIso);
  if (Number.isNaN(start)) return null;
  return Date.now() - start;
}

/**
 * Collects every non-SUCCESS status encountered across stages, so a
 * partial-failure query (e.g. ranking succeeded but citation validation
 * failed) is logged with full context, not just the final node's status.
 */
function collectErrors(stages) {
  const errors = [];
  for (const [stageName, stageData] of Object.entries(stages)) {
    const status = stageData?.status;
    if (status && status.status && status.status !== 'SUCCESS') {
      errors.push({ stage: stageName, status: status.status, reason: status.reason ?? null });
    }
  }
  return errors;
}

// ---- Main -----------------------------------------------------------------

const items = $input.all();
const output = [];

for (const item of items) {
  const currentData = item.json ?? {}; // Workflow 7's formatted output (final node before this)

  const queryStage = safeNodeData(QUERY_PROCESSING_NODE_NAME);
  const retrievalStage = safeNodeData(RETRIEVAL_VALIDATION_NODE_NAME);
  const rankingStage = safeNodeData(RANKING_NODE_NAME);
  const promptStage = safeNodeData(PROMPT_BUILDER_NODE_NAME);
  const citationStage = safeNodeData(CITATION_VALIDATION_NODE_NAME);

  const searchRequest = queryStage.search_request ?? {};
  const requestMetadata = queryStage.request_metadata ?? {};

  const retrievedChunks = Array.isArray(retrievalStage.validated_chunks)
    ? retrievalStage.validated_chunks.map((c) => ({ chunk_uuid: c.chunk_uuid, file_name: c.file_name, score: c.score }))
    : [];

  const selectedChunks = Array.isArray(promptStage.optimized_chunks)
    ? promptStage.optimized_chunks.map((c) => ({
        document_uuid: c.document_uuid,
        file_name: c.file_name,
        tier: c.tier,
        final_score: c.final_score,
      }))
    : [];

  const tokenUsage = normalizeTokenUsage(citationStage.token_usage ?? null);
  const latencyMs = computeLatencyMs(searchRequest.received_at);

  const errors = collectErrors({
    query_processing: queryStage,
    retrieval_validation: retrievalStage,
    ranking: rankingStage,
    citation_validation: citationStage,
    response_formatting: currentData,
  });

  output.push({
    json: {
      request_id: requestMetadata.request_id ?? null,
      session_id: searchRequest.conversation_id ?? null, // no distinct session_id field exists upstream yet
      conversation_id: searchRequest.conversation_id ?? null,
      user_id: searchRequest.user_id ?? null,
      query: searchRequest.normalized_query ?? searchRequest.query ?? null,
      embedding_model: requestMetadata.embedding_model ?? null,
      retrieved_chunks: retrievedChunks,
      selected_chunks: selectedChunks,
      prompt_tokens: tokenUsage.prompt_tokens,
completion_tokens: tokenUsage.completion_tokens,
total_tokens: tokenUsage.total_tokens,
cost_is_estimated_from_total_only: tokenUsage.prompt_tokens == null && tokenUsage.total_tokens != null,
estimated_cost_usd: estimateCost(tokenUsage),
      latency_ms: latencyMs,
      user_feedback: null, // populated later by a separate feedback-update workflow, not this node
      errors,
      logged_at: new Date().toISOString(),
    },
  });
}

return output;
